{
  "context": {
    "action": "catalog/publish",
    "version": "2.0.0",
    "transactionId": "{{$guid}}",
    "messageId": "{{$guid}}",
    "timestamp": "{{now}}",
    "senderId": "{{sender-id}}",
    "receiverId": "{{receiver-id}}"
  },
  "message": {
    "publishDirectives": [
      {
        "catalogId": "cat-pmfby-grievance",
        "catalogType": "REGULAR",
        "updateMode": "MERGE",
        "visibleTo": [
          "{{network-id}}"
        ]
      }
    ],
    "catalogs": [
      {
        "id": "cat-pmfby-grievance",
        "descriptor": {
          "code": "PMFBY-GRIEVANCE",
          "name": "PMFBY Grievance Desk"
        },
        "provider": {
          "id": "{{provider-id}}",
          "descriptor": {
            "code": "PMFBY",
            "name": "PMFBY Grievance Portal"
          }
        },
        "resources": [
          {
            "id": "{{resource-id}}",
            "resourceAttributes": {
              "@context": "{{pack-context}}",
              "@type": "{{capability-code}}",
              "informationMode": "OnDemand",
              "scheme": {
                "code": "PMFBY",
                "name": "Pradhan Mantri Fasal Bima Yojana"
              },
              "grievanceOptions": {
                "categories": [
                  {
                    "code": "3",
                    "name": "Enrollment / Portal Issues",
                    "help": "The only category this desk sends. PMFBY publishes no category list, so every grievance is filed under this one."
                  }
                ],
                "subCategories": [
                  {
                    "code": "10",
                    "name": "Login",
                    "help": "The only sub-category this desk sends, paired with category 3."
                  }
                ]
              },
              "actions": [
                {
                  "action": "support",
                  "description": "File a new grievance. Needs the enrolment number, the applicant's mobile, the crop year, the season and a description of the problem. Returns case.ticketNo, which status requires. Needs no OTP, so it can be called without init.",
                  "schema": "https://openagrinet.github.io/network-specs/schema/Grievance/v0.1/attributes.yaml#/components/schemas/PMFBYSupport",
                  "attributesAt": "$.message.support.channels[0]"
                },
                {
                  "action": "status",
                  "description": "Read where a filed grievance stands: its status code, the portal's reply and the crop it concerns. Needs case.ticketNo from an earlier support call, plus the applicant's mobile. Cases cannot be listed by enrolment number, so support must come first.",
                  "schema": "https://openagrinet.github.io/network-specs/schema/Grievance/v0.1/attributes.yaml#/components/schemas/PMFBYStatus",
                  "attributesAt": "$.message.contract.commitments[0].commitmentAttributes"
                }
              ]
            }
          }
        ],
        "offers": [
          {
            "id": "{{offer-id}}",
            "resourceIds": [
              "{{resource-id}}"
            ]
          }
        ]
      }
    ]
  }
}

{
  "context": {
    "action": "catalog/publish",
    "version": "2.0.0",
    "transactionId": "{{$guid}}",
    "messageId": "{{$guid}}",
    "timestamp": "{{$isoTimestamp}}",
    "senderId": "{{sender-id}}",
    "receiverId": "{{receiver-id}}"
  },
  "message": {
    "publishDirectives": [
      {
        "catalogId": "catalog:scheme-application:pmkisan",
        "catalogType": "REGULAR",
        "updateMode": "MERGE",
        "visibleTo": [
          "{{network-id}}"
        ]
      }
    ],
    "catalogs": [
      {
        "id": "catalog:scheme-application:pmkisan",
        "descriptor": {
          "name": "PM-KISAN application status"
        },
        "provider": {
          "id": "pmkisan",
          "descriptor": {
            "name": "PM-KISAN"
          }
        },
        "resources": [
          {
            "id": "res:pmkisan:application-status",
            "resourceAttributes": {
              "@context": "https://openagrinet.github.io/network-specs/schema/SchemeApplication/v0.1/context.jsonld",
              "@type": "openagrinet:SchemeApplication",
              "informationMode": "OnDemand",
              "scheme": {
                "code": "PM-KISAN",
                "name": "Pradhan Mantri Kisan Samman Nidhi"
              },
              "challenge": {
                "methods": [
                  {
                    "method": "OTP",
                    "channel": "SMS",
                    "length": 4,
                    "valueType": "NUMERIC"
                  }
                ]
              },
              "actions": [
                {
                  "action": "init",
                  "description": "Ask PM-KISAN to send a four-digit OTP, identified by either the registration number or the registered mobile. Call before status, which requires challenge.response carrying this OTP.",
                  "schema": "https://openagrinet.github.io/network-specs/schema/SchemeApplication/v0.1/attributes.yaml#/components/schemas/PMKISANApplicationInit",
                  "attributesAt": "$.message.contract.commitments[0].commitmentAttributes"
                },
                {
                  "action": "status",
                  "description": "Read how far the application has got: when it was registered, the latest instalment paid, whether eKYC is done, and anything blocking payment. Needs the OTP from init, and either the registration number or the registered mobile.",
                  "schema": "https://openagrinet.github.io/network-specs/schema/SchemeApplication/v0.1/attributes.yaml#/components/schemas/PMKISANApplicationStatus",
                  "attributesAt": "$.message.contract.commitments[0].commitmentAttributes"
                }
              ]
            }
          }
        ]
      }
    ]
  }
}
